using System;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;
class InstallerCornerTests {
 [STAThread]static int Main(){foreach(double scale in new[]{1.0,1.25,1.5,2.0}){int width=(int)(80*scale),height=(int)(60*scale);var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.PushTransform(new ScaleTransform(scale,scale));dc.PushOpacityMask(InstallerGlass.CornerMask(80,60));dc.DrawRectangle(Brushes.White,null,new Rect(0,0,80,60));dc.Pop();dc.Pop();}var image=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);image.Render(visual);var pixels=new byte[width*height*4];image.CopyPixels(pixels,width*4,0);if(pixels[3]!=0||pixels[((height/2)*width+width/2)*4+3]!=255)throw new Exception("Mask does not cut the actual corner");int partial=0;for(int i=3;i<pixels.Length;i+=4)if(pixels[i]>0&&pixels[i]<255)partial++;if(partial==0)throw new Exception("Binary jagged mask");Console.WriteLine("PASS smooth alpha edge at "+scale+" scale: "+partial+" partial-alpha pixels");}return 0;}
}
